"""Tests for bin/devtools-check.py: a repository in step with devtools, and its generated files."""

from __future__ import annotations

import importlib.util
import re
import subprocess
import sys
from pathlib import Path

import pytest

SCRIPT = Path(__file__).resolve().parents[2] / "bin" / "devtools-check.py"
spec = importlib.util.spec_from_file_location("devtools_check", SCRIPT)
assert spec and spec.loader
check = importlib.util.module_from_spec(spec)
sys.modules["devtools_check"] = check
spec.loader.exec_module(check)

FETCHER = "#!/usr/bin/env bash\necho fetch\n"


@pytest.fixture
def repo(tmp_path, monkeypatch):
    """A repository in step with devtools: a current fetcher and generated files to match."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "bin").mkdir()
    (tmp_path / "bin" / "devtools-fetch.sh").write_text(FETCHER)
    (tmp_path / ".devtools" / "fetch").mkdir(parents=True)
    (tmp_path / ".devtools" / "fetch" / "devtools-fetch.sh").write_text(FETCHER)
    (tmp_path / "devtools.toml").write_text("[fetch]\n")
    return tmp_path


def write(root: Path, path: str, text: str) -> None:
    """Write a file, creating its directories."""
    (root / path).parent.mkdir(parents=True, exist_ok=True)
    (root / path).write_text(text)


class TestDependabot:
    def test_actions_alone(self):
        text = check.dependabot({})
        header, body = text.split("version: 2\n")
        assert header.startswith("# Generated by devtools-check.py --fix from devtools.toml")
        assert all(line.startswith("#") for line in header.splitlines())
        assert body == (
            "updates:\n"
            '  - package-ecosystem: "github-actions"\n'
            '    directory: "/"\n'
            "    schedule:\n"
            '      interval: "weekly"\n'
            "    cooldown:\n"
            "      default-days: 3\n"
            "    groups:\n"
            "      actions:\n"
            "        patterns:\n"
            '          - "*"\n'
        )

    def test_each_update_with_its_options(self):
        config = {
            "dependabot": {
                "update": [
                    {
                        "ecosystem": "npm",
                        "directory": "/frontend",
                        "group": "frontend",
                        "comment": "The interface.",
                        "ignore": [
                            {
                                "dependency": "typescript",
                                "update_types": ["version-update:semver-major"],
                            }
                        ],
                    },
                    {"ecosystem": "pip", "directory": "/backend", "group": "backend"},
                    {
                        "ecosystem": "gradle",
                        "directory": "/",
                        "update_types": ["minor", "patch"],
                        "cooldown": 0,
                        "ignore": [{"dependency": "org.jetbrains.kotlin:*"}],
                    },
                ]
            }
        }
        text = check.dependabot(config)
        assert (
            "\n  # The interface.\n"
            '  - package-ecosystem: "npm"\n'
            '    directory: "/frontend"\n'
            "    schedule:\n"
            '      interval: "weekly"\n'
            "    cooldown:\n"
            "      default-days: 3\n"
            "      exclude:\n"
            '        - "@jmerhar/*"\n'
            "    ignore:\n"
            '      - dependency-name: "typescript"\n'
            '        update-types: ["version-update:semver-major"]\n'
            "    groups:\n"
            "      frontend:\n"
        ) in text
        assert '      exclude:\n        - "jigkit"\n    groups:\n      backend:\n' in text
        gradle = text.split('"gradle"')[1]
        assert "cooldown" not in gradle
        assert '      - dependency-name: "org.jetbrains.kotlin:*"\n    groups:' in gradle
        assert gradle.endswith(
            '      gradle:\n        patterns:\n          - "*"\n'
            '        update-types:\n          - "minor"\n          - "patch"\n'
        )

    def test_an_explicit_exclude_replaces_the_default(self):
        config = {
            "dependabot": {
                "update": [
                    {
                        "ecosystem": "pip",
                        "directory": "/",
                        "cooldown_exclude": ["mylib"],
                        "cooldown": 7,
                    }
                ]
            }
        }
        text = check.dependabot(config).split('"pip"')[1]
        assert "default-days: 7" in text
        assert '- "mylib"' in text
        assert "jigkit" not in text

    @pytest.mark.parametrize(
        ("table", "message"),
        [
            ({"updates": []}, "[dependabot] has unknown keys: updates"),
            ({"update": [1]}, "[[dependabot.update]] 1 must be a table"),
            ({"update": [{"directory": "/"}]}, "[[dependabot.update]] 1 needs a ecosystem"),
            ({"update": [{"ecosystem": "npm"}]}, "[[dependabot.update]] 1 needs a directory"),
            ({"update": [{"ecosystem": "npm", "directory": "/", "dir": "/"}]}, "unknown keys: dir"),
            (
                {"update": [{"ecosystem": "npm", "directory": "/", "cooldown": -1}]},
                "number of days",
            ),
            (
                {"update": [{"ecosystem": "npm", "directory": "/", "cooldown": True}]},
                "must be a int",
            ),
            ({"update": [{"ecosystem": "npm", "directory": "/", "group": "a b"}]}, "group must be"),
            (
                {"update": [{"ecosystem": "npm", "directory": "/", "ignore": [{}]}]},
                "needs a dependency",
            ),
            (
                {
                    "update": [
                        {
                            "ecosystem": "npm",
                            "directory": "/",
                            "ignore": [{"dependency": "x", "y": 1}],
                        }
                    ]
                },
                "ignore has unknown keys: y",
            ),
            (
                {"update": [{"ecosystem": "npm", "directory": "/", "update_types": [{}]}]},
                "must list strings",
            ),
            (
                {
                    "update": [
                        {
                            "ecosystem": "npm",
                            "directory": "/",
                            "ignore": [{"dependency": "x", "update_types": [1]}],
                        }
                    ]
                },
                "ignore update_types must list strings",
            ),
            (
                {"update": [{"ecosystem": "github-actions", "directory": "/"}]},
                "dependabot lists github-actions in / twice",
            ),
        ],
    )
    def test_refuses_a_malformed_table(self, table, message):
        with pytest.raises(check.CheckError) as e:
            check.dependabot({"dependabot": table})
        assert message in str(e.value)


class TestCodecov:
    def test_one_carried_forward_flag_per_suite_with_its_paths(self):
        coverage = {"suites": {"backend": {}, "frontend": {}}}
        text = check.codecov({"codecov": {"paths": {"backend": ["backend/"]}}}, coverage)
        assert text.endswith(
            "comment: false\n\nflags:\n"
            "  backend:\n    paths:\n      - backend/\n    carryforward: true\n"
            "  frontend:\n    carryforward: true\n"
        )
        assert "informational: true" in text

    def test_no_flags_without_suites(self):
        assert check.codecov({}, {}).endswith("comment: false\n")

    @pytest.mark.parametrize(
        ("table", "message"),
        [
            ({"path": {}}, "[codecov] has unknown keys: path"),
            ({"paths": {"web": ["web/"]}}, "names suites coverage.toml lacks: web"),
            ({"paths": {"backend": "backend/"}}, "paths backend must list paths"),
        ],
    )
    def test_refuses_a_malformed_table(self, table, message):
        with pytest.raises(check.CheckError, match=re.escape(message)):
            check.codecov({"codecov": table}, {"suites": {"backend": {}}})


class TestChecks:
    def test_a_repository_in_step(self, repo):
        assert check.checks(repo, fix=True) == []
        assert check.checks(repo) == []
        assert (repo / ".github" / "dependabot.yml").is_file()
        assert not (repo / "codecov.yml").exists()

    def test_writes_codecov_when_there_is_a_coverage_toml(self, repo):
        write(repo, "coverage.toml", "[suites.backend]\nformat = 'coveragepy'\n")
        assert check.checks(repo, fix=True) == []
        assert "  backend:\n    carryforward: true\n" in (repo / "codecov.yml").read_text()

    def test_reports_generated_files_that_differ(self, repo):
        write(repo, "coverage.toml", "[suites.backend]\n")
        check.checks(repo, fix=True)
        write(repo, ".github/dependabot.yml", "version: 2\n")
        (repo / "codecov.yml").unlink()
        problems = check.checks(repo)
        assert [p.split(" is not")[0] for p in problems] == [
            ".github/dependabot.yml",
            "codecov.yml",
        ]
        assert all(p.endswith("generates; run devtools-check.py --fix") for p in problems)

    def test_reports_a_stale_fetcher(self, repo):
        check.checks(repo, fix=True)
        (repo / "bin" / "devtools-fetch.sh").write_text(FETCHER + "# old\n")
        [problem] = check.checks(repo)
        assert problem.startswith(
            "bin/devtools-fetch.sh differs from the fetcher at the pinned ref"
        )

    def test_needs_the_fetched_fetcher_to_compare_with(self, repo):
        check.checks(repo, fix=True)
        (repo / ".devtools" / "fetch" / "devtools-fetch.sh").unlink()
        assert check.checks(repo) == [
            'add "fetch/devtools-fetch.sh" to [fetch] files, so the fetcher can be compared'
        ]

    def test_skips_the_fetcher_when_there_is_none(self, repo):
        (repo / "bin" / "devtools-fetch.sh").unlink()
        (repo / ".devtools" / "fetch" / "devtools-fetch.sh").unlink()
        write(repo, "devtools.toml", '[check]\nfetcher = ""\n')
        assert check.checks(repo, fix=True) == []

    def test_finds_the_fetcher_where_check_says(self, repo):
        (repo / "bin" / "devtools-fetch.sh").rename(repo / "fetcher.sh")
        assert check.checks(repo, fix=True) == [
            "no fetcher at bin/devtools-fetch.sh; set [check] fetcher"
        ]
        write(repo, "devtools.toml", '[check]\nfetcher = "fetcher.sh"\n')
        assert check.checks(repo, fix=True) == []

    @pytest.mark.parametrize(
        ("path", "text", "problem"),
        [
            ("ruff.toml", 'extend = ".devtools/config/ruff.toml"\n', None),
            ("ruff.toml", "line-length = 100\n", "ruff.toml does not extend"),
            (
                "pyproject.toml",
                "[tool.ruff]\nline-length = 100\n",
                "pyproject.toml does not extend",
            ),
            (
                "backend/pyproject.toml",
                '[tool.ruff]\nextend = "../.devtools/config/ruff.toml"\n',
                None,
            ),
            (
                "backend/pyproject.toml",
                '[tool.ruff]\nextend = ".devtools/config/ruff.toml"\n',
                "backend",
            ),
            ("backend/pyproject.toml", "[project]\nname = 'x'\n", None),
        ],
    )
    def test_the_ruff_configuration_extends_the_base(self, repo, path, text, problem):
        write(repo, path, text)
        problems = check.checks(repo, fix=True)
        if problem is None:
            assert problems == []
        else:
            [found] = problems
            assert found.startswith(problem)

    def test_the_base_can_be_named(self, repo):
        write(repo, "ruff.toml", 'extend = "config/ruff.toml"\n')
        assert check.checks(repo, fix=True) == [
            "ruff.toml does not extend .devtools/config/ruff.toml"
        ]
        write(repo, "devtools.toml", '[check]\nruff_base = "config/ruff.toml"\n')
        assert check.checks(repo, fix=True) == []

    def test_refuses_invalid_files(self, repo):
        write(repo, "ruff.toml", "[x\n")
        with pytest.raises(check.CheckError, match="ruff.toml is not valid TOML"):
            check.checks(repo)
        write(repo, "devtools.toml", "[x\n")
        with pytest.raises(check.CheckError, match="devtools.toml is not valid TOML"):
            check.checks(repo)
        (repo / "devtools.toml").unlink()
        with pytest.raises(check.CheckError, match="no devtools.toml"):
            check.checks(repo)
        write(repo, "devtools.toml", "check = 1\n")
        with pytest.raises(check.CheckError, match=r"\[check\] must be a table"):
            check.checks(repo)


class TestMain:
    def test_reports_problems_with_status_1(self, repo, capsys):
        assert check.main([]) == 1
        assert "dependabot.yml is not what devtools.toml generates" in capsys.readouterr().err

    def test_fix_then_in_step(self, repo, capsys):
        assert check.main(["--fix"]) == 0
        assert capsys.readouterr().out == "devtools-check: in step with devtools\n"

    def test_reports_a_malformed_config(self, repo, capsys):
        write(repo, "devtools.toml", "[dependabot]\nupdates = []\n")
        assert check.main([]) == 1
        assert capsys.readouterr().err == "devtools-check: [dependabot] has unknown keys: updates\n"


def test_runs_as_a_script(repo):
    result = subprocess.run(
        [sys.executable, str(SCRIPT), "--fix"], capture_output=True, text=True, check=False
    )
    assert (result.returncode, result.stdout) == (0, "devtools-check: in step with devtools\n")
